<?php require "db.php";$q=trim($_GET["q"]??"");$loc=trim($_GET["loc"]??"");$cat=$_GET["cat"]??"";$type=$_GET["type"]??"";$remote=$_GET["remote"]??"0";$sql="SELECT id,title,company,location,salary,category,job_type,description,posted_at FROM jobs WHERE 1=1";$p=[];if($q!==""){$sql.=" AND (title LIKE ? OR company LIKE ? OR description LIKE ?)";$x="%$q%";array_push($p,$x,$x,$x);}if($loc!==""){$sql.=" AND location LIKE ?";$p[]="%$loc%";}if($cat!==""){$sql.=" AND category=?";$p[]=$cat;}if($type!==""){$sql.=" AND job_type=?";$p[]=$type;}if($remote==="1")$sql.=" AND (location LIKE '%remote%' OR job_type='Remote')";$sql.=" ORDER BY posted_at DESC";$s=$pdo->prepare($sql);$s->execute($p);done($s->fetchAll());?>